-- CampBuddy — Punkte für die Region CH.
-- Ausführen: Supabase-Projekt -> SQL Editor -> Inhalt einfügen -> Run.
--
-- 955 Punkte aus OpenStreetMap (ODbL): 438 campsite, 318 hut, 199 vehicle_spot.
-- Kein Prüfdatum: keiner dieser Punkte ist selbst nachgesehen.


begin;
on conflict (id) do update set region = excluded.region, type = excluded.type, name = excluded.name, lat = excluded.lat, lng = excluded.lng, elevation = excluded.elevation, info = excluded.info, source = excluded.source, source_url = excluded.source_url, updated_at = now();
commit;
